#!/bin/sh
# Purpose: selftest case — ViD's decision on a row and a ticket (v0.26.10.24.6 R1, R2, R5, R6), on the results reader's made-up reports.
# No decision without its evidence file. Each line of the table: accepted, failing, evidence missing, question open, owed, passing; the sort line; a
# fault value ending extra; a skeleton's one fault; a journey; the ticket, with a new head starting again; a weak test's
# siblings, several items among them; the standing line only with a product failure; no file path in a comment, whatever the reports hold; a
# blocked issue; a comment posted once, and again on a change. Nothing reaches the handed record for an unmerged ticket; on merged, with
# plan.sh and the writer reading each word, fault-proven, a journey's line and declare called; a recorded row to failing and back, its mark kept.
# v0.26.10.25.3: the engine line and the split line after the rows, engine-split once a row, the split line for a ticket asking fewer engines (R11); analyst due once a ticket (R12).
# v0.26.10.26.3 (R2): accepted-at, one line a ticket at its first acceptance, never again. Env: CHECKS.
set -eu
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
. "$CHECKS/selftest/fixtures/tickets.sh"
. "$CHECKS/selftest/fixtures/results-reports.sh"
fail() { echo "decide-rows: $*" >&2; cat "$T/out" >&2 2>/dev/null; exit 1; }
RS=$CHECKS/results.sh; DS=$CHECKS/decide.sh; rr_project; : > .vid/RUN-STATE.md; printf 'repo: owner/code\nlabels-prefix:\n' > .vid/tw/settings
git init -q --bare "$T/code.git"; gh_fake; mv "$T/bin/gh" "$T/bin/gh-fake"
cat > "$T/bin/gh" <<'G'
#!/bin/sh
case "$1 $2 ${7:-}" in 'pr view labels') cat "$FAKEGH/prs/$3/labels" 2>/dev/null | paste -sd , -; exit 0 ;; 'pr view body') printf 'ticket: #x\n\nDecisions: none\n'; exit 0 ;; esac
exec "$(dirname "$0")/gh-fake" "$@"
G
chmod +x "$T/bin/gh"; for n in 1 2 3 5 7; do mkdir -p "$T/gh/issues/$n/comments"; echo OPEN > "$T/gh/issues/$n/state"; done; mkdir -p "$T/gh/prs/4/comments" "$T/gh/prs/2/comments"
H=$RR_H12; H2=$(printf %s "$RR_H2" | cut -c1-12); A=pr-4-$H-2; G=sort-pr-4-$H-1
# fresh: these rounds read each head on its own; KEEP=1 keeps the earlier set
fresh() { [ -n "${KEEP:-}" ] && return 0; for f in .vid/decide/pr-*.rows; do [ -f "$f" ] && awk -F'\t' -v OFS='\t' '{ $10 = 0; print }' "$f" > "$T/rw" && cat "$T/rw" > "$f"; done; return 0; }
dc() { fresh; sh "$RS" read --ticket "${2:-3}" --pr "${3:-4}" --head "$1" > /dev/null 2>&1; RC=0; sh "$DS" decide --ticket "${2:-3}" --pr "${3:-4}" --head "$1" ${4:-} > "$T/out" 2>&1 || RC=$?; [ "$RC" = 0 ] || fail "decide exited $RC"; }
is() { grep -q "^$1 $2" "$T/out" || fail "no line: $1 $2"; }
RC=0; sh "$DS" decide --ticket 3 --pr 4 --head "$RR_H" > "$T/out" 2>&1 || RC=$?; [ "$RC" = 1 ] && grep -q 'no evidence file' "$T/out" || fail 'a decision with no evidence file'
# a first round: red, passed, kept; no fault folder; a grader's question
rr_good; A=pr-4-$H-2; dc "$RR_H"; is 'ticket:' 'not yet'; is ROW-001 'accepted$'; is ROW-002-T1 'evidence missing — no fault folder, pr-4'; is ROW-002-T2 accepted; is ROW-002 'not accepted'; is HOS-001 'evidence missing'; is RULE-001 accepted
is DIF-001 'owed$'; is SEAM-001 'owed$'; is ROW-009 'passing$'; [ ! -s .vid/tw/handed ] || fail 'an unmerged ticket reached the handed record'; grep -q 'product failure\|Fix the whole harm' "$T/out" && fail 'the standing line with no product failure'
# every needed fault proven, a fault nobody needed, the grade kept: the ticket accepted, and owed rows with it
mkdir -p "$T/r/$A/faults"; cp "$T/r/pr-4-$H-1/results.txt" "$T/r/pr-4-$H-1/cases-alpha.xml" "$T/r/$A/"; fa() { rr_put "$A" "faults/$1/control.txt" "$2"; rr_put "$A" "faults/$1/cases-alpha.xml" "$(rr_cases "$1=${3:-fail:no}" "$2=pass")"; }
fa ROW-002-T1 ROW-001; fa HOS-001 ROW-001 'fail:two&#10;vid-forbidden-effect: HOS-001'; rr_send "$A"
dc "$RR_H"; is 'ticket:' accepted; is ROW-002 accepted; is SEAM-001 'owed$'; is ROW-002-T1 'accepted$'; is HOS-001 'accepted$'; grep -q 'Fix the whole harm' "$T/out" && fail 'the standing line with no product failure'
[ "$(grep -c . .vid/decide/accepted-at)" = 1 ] && grep -q "^4 3 $H at=20[0-9-]*T[0-9:]*Z$" .vid/decide/accepted-at || fail "accepted-at is not one line for the first acceptance: $(cat .vid/decide/accepted-at)"   # v0.26.10.26.3 (R2)
# proven extra stands for no needed fault, missing extra and inconclusive extra are no missing evidence, not-proven extra is failing
fa ROW-001 HOS-001; fa RULE-001 HOS-001 pass; rr_send "$A"; dc "$RR_H"; is ROW-001 'accepted$'; is RULE-001 'failing, a weak test — its fault not proven'
rm -rf "$T/r/$A/faults/RULE-001"; rr_send "$A"
# the posted comment, once a head and again on a change
dc "$RR_H" 3 4 --post; dc "$RR_H" 3 4 --post; [ "$(ls "$T/gh/prs/4/comments" | wc -l | tr -d ' ')" = 1 ] || fail 'not one comment'; head -n 1 "$T/gh/prs/4/comments/1" | grep -qx "vid: decision $RR_H" || fail 'the comment has no first line'
# a later head: failing, a weak test and its siblings by several items, scope:, a blocked issue, no path in a comment, the reason in no comment
printf '```vid-inventory\nROW-001 | b | c | d | e | f | REQ-001, INV-002 | x\nROW-002 | b | c | d | e | f | REQ-001 | x\nROW-006 | b | c | d | e | f | INV-002 | x\nROW-007 | b | c | d | e | f | REQ-009 | x\n```\n' > INVENTORY.md
Q=pr-4-$H2-1; S2=sort-pr-4-$H2-1; rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$RR_H2")"; rr_put "$Q" cases-alpha.xml "$(rr_cases 'ROW-001=pass' ROW-002-T1=fail:see\ apps/web/views.py ROW-002-T2=pass HOS-001=pass RULE-001=pass ROW-009=pass)"; rr_put "$Q" faults/ROW-001/control.txt ROW-009; rr_put "$Q" faults/ROW-001/cases-alpha.xml "$(rr_cases ROW-001=pass ROW-009=pass)"; rr_send "$Q"
dc "$RR_H2"; is 'ticket:' 'not yet'; is ROW-001 "failing, a weak test — its fault not proven, $Q — siblings: ROW-002, ROW-006, and any other test with the same data pattern"; is ROW-002-T1 "failing, a product failure — its test failed, $Q"; is HOS-001 'accepted$'; is RULE-001 'accepted$'; grep -q 'sort evidence missing' "$T/out" && fail 'the sort asked with its report there'
# v0.26.10.25.2 R3: the sort's line comes beside a failing row
git --git-dir=.vid/code update-ref -d "refs/heads/vid-results/sort-pr-4-$H-1"; dc "$RR_H2"; is ROW-001 'failing, a weak test'; is ROW-002-T1 'failing, a product failure'; is 'sort evidence' 'missing — no sort report'; rr_send "sort-pr-4-$H-1"
grep -q 'Fix the whole harm' "$T/out" || fail 'no standing line with a product failure'; grep -qE '\.py|apps/|tests/' "$T/out" && fail 'a file path in a comment'; rm -f INVENTORY.md
# no grade line stands on a row; with every fault in place and no sort report the one line asks for it; a blocked issue
rr_put "$Q" faults/HOS-001/control.txt ROW-009; rr_put "$Q" faults/HOS-001/cases-alpha.xml "$(rr_cases 'HOS-001=fail:x&#10;vid-forbidden-effect: HOS-001' ROW-009=pass)"; rr_put "$Q" cases-alpha.xml "$(rr_cases $RR_ALL)"; rr_put "$Q" faults/ROW-002-T1/control.txt ROW-009; rr_put "$Q" faults/ROW-002-T1/cases-alpha.xml "$(rr_cases ROW-002-T1=fail:x ROW-009=pass)"; rm -rf "$T/r/$Q/faults/ROW-001"; rr_send "$Q"
git --git-dir=.vid/code update-ref -d "refs/heads/vid-results/sort-pr-4-$H-1"; git --git-dir=.vid/code update-ref -d "refs/heads/vid-results/grade-pr-4-$H-1"; dc "$RR_H2"; is HOS-001 'accepted$'; is 'ticket:' 'not yet'; is 'sort evidence' 'missing — no grade report'; rr_send "grade-pr-4-$H-1"; dc "$RR_H2"; is 'sort evidence' 'missing — no sort report'; rr_put "$S2" sorted.txt 'by: TM'; rr_send "$S2"; dc "$RR_H2"; is 'sort evidence' "missing — sort report refused, $S2"; rr_put "$S2" sorted.txt "$(printf 'by: SR\ncommit: %s\nROW-001 note it — it fits — a word\nROW-009 drop it — no use — another' "$RR_H2")"; rr_send "$S2"; dc "$RR_H2"; is 'ticket:' accepted; sh "$DS" queue > /dev/null; grep -q 'note .*it fits — a word' .vid/decide/queue.md && ! grep -q 'no use' .vid/decide/queue.md || fail 'a note did not reach the queue, or a drop did'; echo blocked > "$T/gh/issues/3/labels"; dc "$RR_H2"; is 'ticket:' 'not yet'; is ROW-009 'question open'; is DIF-001 'question open'; : > "$T/gh/issues/3/labels"; echo blocked > "$T/gh/prs/4/labels"; dc "$RR_H2"; is ROW-009 'question open'; : > "$T/gh/prs/4/labels"
# 0.26.10.28.10 (R1): a follow-up ticket (its header's follows: line) asks no T5: no grade and no sort is owed, and the runs accept it
cp .vid/tw/out/issue-3.md "$T/i3"; awk '{ print } /^- rows: / && !d { print "- follows: #1"; d = 1 }' "$T/i3" > .vid/tw/out/issue-3.md; git --git-dir=.vid/code update-ref -d "refs/heads/vid-results/$S2"; git --git-dir=.vid/code update-ref -d "refs/heads/vid-results/grade-pr-4-$H-1"; dc "$RR_H2"; ! grep -q 'sort evidence' "$T/out" || fail 'a follow-up was asked for its grade or sort'; is 'ticket:' accepted; cp "$T/i3" .vid/tw/out/issue-3.md; rr_send "grade-pr-4-$H-1"; rr_send "$S2"; dc "$RR_H2"; is 'ticket:' accepted
# a skeleton: one row's proven fault stands for the others' missing
sed 's/^- ROW-009 marks: none$/&\n> ROW-010 | behavior | a | b | n\/a | More. | REQ-001 | origin: REQ-001\n- ROW-010 marks: none/' .vid/tw/out/issue-1.md > .vid/tw/out/issue-7.md; S=pr-2-$H-1
rr_put "$S" results.txt "$(printf 'by: TM\ncommit: %s\nengines: alpha\nenvironments: 2' "$RR_H")"; rr_put "$S" cases-alpha.xml "$(rr_cases ROW-009=pass ROW-010=pass)"; rr_put "$S" faults/ROW-009/cases-alpha.xml "$(rr_cases ROW-009=fail:gone)"; rr_send "$S"
rr_put grade-pr-2-$H-1 grade.txt "$(printf 'by: GR\ncommit: %s\nROW-009 kept — a\nROW-010 kept — b' "$RR_H")"; rr_send grade-pr-2-$H-1; dc "$RR_H" 7 2; is ROW-009 'accepted$'; is ROW-010 'accepted$'; is 'ticket:' accepted
# merged: the rows enter; a recorded row goes to failing, keeps its mark, and comes back; declare runs; the writer and plan.sh read every word
sh "$DS" merged --pr 2 > "$T/out" 2>&1 || fail 'merged failed'; grep -qx 'row ROW-009 accepted fault-proven | stand-in: decision' .vid/tw/handed && grep -qx 'row ROW-010 accepted | stand-in: decision' .vid/tw/handed || fail 'the merged lines'; grep -qx 'engines alpha | stand-in: results reader' .vid/tw/handed && grep -qx 'stacks=2' .vid/budget || fail 'declare did not run'
dc "$RR_H"; dc "$RR_H" 3 4; is 'ticket:' accepted; sh "$DS" merged --pr 4 > "$T/out" 2>&1; grep -qx 'row ROW-002 accepted fault-proven | stand-in: decision' .vid/tw/handed && grep -qx 'row HOS-001 accepted fault-proven | stand-in: decision' .vid/tw/handed && grep -qx 'row DIF-001 owed | stand-in: decision' .vid/tw/handed || fail 'a journey or an owed row on merge'
[ "$(grep -c '^4 3 ' .vid/decide/accepted-at)" = 1 ] && grep -q "^2 7 $H at=" .vid/decide/accepted-at || fail 'accepted-at is written again on a later acceptance, or not for ticket 7'
rr_put "$Q" cases-alpha.xml "$(rr_cases 'ROW-001=pass' ROW-002-T1=fail:broke ROW-002-T2=pass HOS-001=pass RULE-001=pass ROW-009=pass)"; rr_send "$Q"; dc "$RR_H2"; grep -qx 'row ROW-002 failing fault-proven | stand-in: decision' .vid/tw/handed || fail 'a recorded row did not go to failing with its mark'
rr_put "$Q" cases-alpha.xml "$(rr_cases $RR_ALL)"; rr_send "$Q"; rr_put grade-pr-4-$H2-1 grade.txt "$(printf 'by: GR\ncommit: %s\nROW-001 breached product — wrong\nHOS-001 unclear — which?' "$RR_H2")"; rr_send grade-pr-4-$H2-1; dc "$RR_H2"; is 'ticket:' accepted; is ROW-001 'accepted$'; is HOS-001 'accepted$'; grep -qx 'row ROW-002 accepted fault-proven | stand-in: decision' .vid/tw/handed || fail 'a recorded row did not come back'
[ "$(cut -f2 .vid/decide/rows/ROW-002-T1.txt | tail -n 1)" = "$H2" ] && [ "$(cut -f3 .vid/decide/rows/ROW-002-T1.txt | tail -n 1)" = answered ] || fail 'the record does not say what answered it'
# a failing row keeps its missing evidence in its line
rr_put "$Q" cases-alpha.xml "$(rr_cases 'ROW-001=pass' ROW-002-T1=fail:broke ROW-002-T2=pass HOS-001=pass RULE-001=pass ROW-009=pass)"; rm -rf "$T/r/$Q/faults/ROW-002-T1"; rr_send "$Q"; dc "$RR_H2"
is ROW-002-T1 "failing, a product failure — its test failed, $Q"
# a refused T2 counts by its report; a held journey's retested transitions stay held, and merged leaves them; an older merge leaves a newer hold
rr_put red-3-2 results.txt "$(printf 'by: GR\ncommit: %s\nrows: ROW-001' "$RR_RED")"; rr_put red-3-2 cases-alpha.xml "$(rr_cases ROW-001=fail:x)"; rr_send red-3-2; dc "$RR_H2"; is ROW-001 'evidence missing — T2 refused, red-3-2'; grep -qx 'ROW-001 red-3-2' .vid/decide/counts || fail 'a refused T2 is no count'; git --git-dir=.vid/code update-ref -d refs/heads/vid-results/red-3-2
sed -e 's/^- ROW-009$/- ROW-002/' -e '/^## Rows$/,/^## Engines$/{/ROW-002/d;}' -e 's/^- ROW-002-T1 (of.*$/- HOS-001: x/' .vid/tw/out/issue-3.md > .vid/tw/out/issue-9.md; mkdir -p "$T/gh/issues/9/comments"; echo OPEN > "$T/gh/issues/9/state"; mkdir -p "$T/gh/prs/8/comments"; printf 'ROW-002 a\nROW-002 b\n' >> .vid/decide/counts
J=pr-8-$H2-1; rr_put "$J" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 1\nretested: ROW-002' "$RR_H2")"; rr_put "$J" cases-alpha.xml "$(rr_cases $RR_ALL)"; for r in ROW-002-T1 ROW-002-T2 HOS-001; do rr_put "$J" faults/$r/control.txt ROW-001; rr_put "$J" faults/$r/cases-alpha.xml "$(rr_cases "$r=fail:x&#10;vid-forbidden-effect: $r" ROW-001=pass)"; done; rr_send "$J"
dc "$RR_H2" 9 8; is ROW-002-T1 'held'; is ROW-002-T2 'held'; is 'ticket:' 'not yet'; grep -q '^row ROW-002 held' .vid/tw/handed || fail 'a held journey lost its held line'; sh "$DS" merged --pr 4 > "$T/out" 2>&1; grep -q '^row ROW-002 held' .vid/tw/handed || fail 'an older merge erased a newer hold'
# R1: a row stopped at setup: is evidence missing by its report, an accept undone, a second report holding it. R6: a proven fault stands past an inconclusive one and a failing head, not past retested:, and not-proven wins
KEEP=1; rm -rf .vid/decide; cp .vid/tw/handed "$T/kept"; nh() { rr_git -C "$T/w" commit -q --allow-empty -m "$1"; X=$(git -C "$T/w" rev-parse HEAD); git -C "$T/w" push -q "$T/p/.vid/code" main; h=$(printf %s "$X" | cut -c1-12); Q=pr-14-$h-1; rr_put "$Q" faults/ROW-002-T1/control.txt ROW-009; rr_put "$Q" faults/ROW-002-T1/cases-alpha.xml "$(rr_cases ROW-002-T1=fail:x ROW-009=pass)"; }
rp() { rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2\n%s' "$X" "$1")"; c=$2; shift 2; rr_put "$Q" cases-alpha.xml "$(rr_cases ROW-001=pass ROW-002-T1=pass ROW-002-T2=pass RULE-001=pass ROW-009=pass "$c")"; [ -n "${NF:-}" ] || { rr_put "$Q" faults/HOS-001/control.txt ROW-009; rr_put "$Q" faults/HOS-001/cases-alpha.xml "$(rr_cases "$@" ROW-009=pass)"; }; rr_send "$Q"; dc "$X" 3 14; }
fv() { [ "$(awk -F'\t' '$1 == "HOS-001" { print $5 }' ".vid/decide/pr-14-$h.rows")" = "$1" ] || fail "HOS-001's fault at $2 is not $1"; }; PF='HOS-001=fail:x&#10;vid-forbidden-effect: HOS-001'
nh r1; rp '' HOS-001=pass "$PF"; fv proven 'its proof'; nh r2; rp '' HOS-001=pass HOS-001=err:boom; fv proven 'an inconclusive fault'; nh r3; rp '' HOS-001=fail:broke "$PF"; fv proven 'a failing head'; nh r3b; NF=1; rp 'reached: HOS-001' HOS-001=pass; NF=; is HOS-001 'evidence missing — no fault folder'; fv proven 'a reached head with no folder'; nh r3c; rp '' HOS-001=pass HOS-001=err:boom; fv proven 'an inconclusive fault after it'; nh r4; rp 'retested: HOS-001' HOS-001=pass HOS-001=err:boom; fv inconclusive 'a retested head'; nh r5; rp '' HOS-001=pass "$PF"; fv proven 'a new proof'; nh r6; rp '' HOS-001=pass HOS-001=pass; fv not-proven 'a later not-proven'; is HOS-001 'failing, a weak test'
nh r7; rp '' HOS-001=pass "$PF"; printf 't\tHOS-001\taccept\t\tx\n' >> .vid/decide/rulings; echo 'row HOS-001 accepted-by-ruling | stand-in: x' >> .vid/tw/handed; nh r8; rp '' HOS-001=err:setup:\ no\ door "$PF"; is HOS-001 "evidence missing — its test could not run, $Q"; grep -q 'no door\|product failure' "$T/out" && fail 'a setup: row names its words, or a product failure'; grep -q 'HOS-001.undone' .vid/decide/rulings && grep -q '^row HOS-001 failing' .vid/tw/handed || fail 'an accept stood on a row that could not run'
Q=pr-14-$h-2; rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$X")"; rr_put "$Q" cases-alpha.xml "$(rr_cases ROW-001=pass ROW-002-T1=pass ROW-002-T2=pass RULE-001=pass ROW-009=pass HOS-001=err:setup:\ no\ door)"; rr_send "$Q"; dc "$X" 3 14; is HOS-001 'held — evidence missing — its test could not run'
nh r9; rp '' HOS-001=pass "$PF"; G9=grade-pr-14-$h-1; rr_put "$G9" grade.txt "$(printf 'by: GR\ncommit: %s\nROW-001 breached test — x' "$X")"; rr_send "$G9"; dc "$X" 3 14; is 'sort evidence' 'missing — no sort report'; sh "$DS" rule ROW-001 limit > /dev/null; dc "$X" 3 14; grep -q 'sort evidence' "$T/out" && fail 'a sort asked for a known limit alone'; cat "$T/kept" > .vid/tw/handed
# v0.26.10.25.3 R11: an engine not asked, its line and its split as ticket-level lines after the rows; engine-split written once a row; once split, a ticket asking fewer engines is told
mkdir -p "$T/gh/prs/20/comments" "$T/gh/prs/21/comments"; Q=pr-20-$H-1; rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$RR_H")"; rr_put "$Q" cases-alpha.xml "$(rr_cases $RR_ALL)"; rr_put "$Q" cases-beta.xml "$(rr_cases RULE-001=fail:only\ beta ROW-002-T1=err:setup:\ x)"; rr_send "$Q"; dc "$RR_H" 3 20
is RULE-001 'failing, a product failure'; awk '/^ROW-002 not accepted/ { a = NR } /^engine beta: 5 could not run$/ { b = NR } /^split — every engine is now asked: alpha beta$/ { c = NR } /^sort evidence missing/ { d = NR } /^Fix the whole harm/ { e = NR } END { exit !(a && a < b && b < c && c < d && d < e) }' "$T/out" || fail 'the engine and split lines, or their place'
grep -qx 'engine-split RULE-001 | stand-in: alpha beta' .vid/tw/handed || fail 'no engine-split line'; dc "$RR_H" 3 20; [ "$(grep -c '^engine-split ' .vid/tw/handed)" = 1 ] || fail 'engine-split written twice'
sed 's/^engines alpha |/engines alpha beta |/' .vid/tw/handed > "$T/h"; cat "$T/h" > .vid/tw/handed; Q=pr-20-$H2-1; rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$RR_H2")"; rr_put "$Q" cases-alpha.xml "$(rr_cases $RR_ALL)"; rr_put "$Q" cases-beta.xml "$(rr_cases $RR_ALL)"; rr_send "$Q"; dc "$RR_H2" 3 20
is RULE-001 'accepted$'; grep -qx 'split — every engine is now asked: alpha beta' "$T/out" && ! grep -q '^engine ' "$T/out" || fail 'a ticket asking fewer engines than declared was not told'; cat "$T/kept" > .vid/tw/handed
# R12: analyst due once a ticket, when the pull request's head reports reach 5 setup: errors, at that head alone
Q=pr-21-$H-1; rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$RR_H")"; rr_put "$Q" cases-alpha.xml "$(rr_cases ROW-001=err:setup:\ a ROW-002-T1=err:setup:\ b HOS-001=err:setup:\ c ROW-002-T2=pass RULE-001=pass ROW-009=pass)"; rr_send "$Q"; dc "$RR_H" 3 21; grep -q '^analyst due' "$T/out" && fail 'analyst due at 3'
Q=pr-21-$H2-1; rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$RR_H2")"; rr_put "$Q" cases-alpha.xml "$(rr_cases ROW-001=err:setup:\ a ROW-002-T1=fail:setup:\ b HOS-001=pass ROW-002-T2=pass RULE-001=pass ROW-009=pass)"; rr_send "$Q"; dc "$RR_H2" 3 21; is 'analyst due' '— alpha, 5 cases could not run over 2 runs$'; is 'ticket:' 'not yet'
dc "$RR_H2" 3 21; is 'analyst due' '— alpha, 5'; dc "$RR_H" 3 21; grep -q '^analyst due' "$T/out" && fail 'analyst due twice a ticket'
# v0.26.10.25.4: a regression row a close found red, its fix not merged, fails here: its state stands, no count, its handed line kept
mkdir -p "$T/gh/prs/22/comments" .vid/decide/close/S09/1; printf 'issue\t40\ncommit\t%s\n' "$RR_H" > .vid/decide/close/S09/1/ask; printf 'ROW-009\tROW-009 in alpha\n' > .vid/decide/close/S09/1/acted
grep -v '^row ROW-009 ' .vid/tw/handed > "$T/h" || true; echo 'row ROW-009 failing | stand-in: close #40' >> "$T/h"; cat "$T/h" > .vid/tw/handed; cp .vid/decide/counts "$T/c0"
Q=pr-22-$H-1; rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$RR_H")"; rr_put "$Q" cases-alpha.xml "$(rr_cases ROW-001=pass ROW-002-T1=pass ROW-002-T2=pass HOS-001=pass RULE-001=pass ROW-009=fail:broke)"; rr_send "$Q"; dc "$RR_H" 3 22
is ROW-009 'its state stands$'; ! grep -q '^ROW-009 ' "$T/c0" && grep -q '^ROW-009 ' .vid/decide/counts && fail 'the owned row was counted'; grep -qx 'row ROW-009 failing | stand-in: close #40' .vid/tw/handed || fail 'the owned row left its handed line'
Q=pr-22-$H2-1; rr_put "$Q" results.txt "$(printf 'by: TM\ncommit: %s\ncovers: RULE-001 2' "$RR_H2")"; rr_put "$Q" cases-alpha.xml "$(rr_cases $RR_ALL)"; rr_send "$Q"; dc "$RR_H2" 3 22; is ROW-009 'passing$'
sh "$DS" merged --pr 22 > "$T/out" 2>&1 || fail 'the merge failed'; grep -qx 'row ROW-009 failing | stand-in: close #40' .vid/tw/handed || fail 'a merge passing the owned row made it accepted'
rm -rf .vid/decide/close; grep -v '^row ROW-009 ' .vid/tw/handed > "$T/h" || true; cat "$T/h" > .vid/tw/handed
cp .vid/tw/handed "$T/handed"; . "$CHECKS/selftest/fixtures/tw-toy.sh"; tw_toy "$T/toy"; { echo 'candidate 0 | stand-in: x'; cat "$T/handed"; printf 'row ROW-003 held | stand-in: decision\nrow ROW-004 failing fault-proven | stand-in: decision\nrow ROW-001 known-limit | stand-in: decision\nrow ROW-002 accepted-by-ruling | stand-in: decision\n'; } > .vid/tw/handed
sed -i.b 's/^engines alpha/engines chromium/' .vid/tw/handed; rm -f .vid/tw/handed.b; sh "$CHECKS/writer.sh" gate > "$T/out" 2>&1 || fail 'the writer refused a word'; tw_start S01 || { cat "$T/start" > "$T/out"; fail 'plan.sh refused a word'; }
exit 0
